import{_ as e,c as r,o,al as t}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"ROS 2","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ros2/index.md","filePath":"zh/ros2/index.md"}'),s={name:"zh/ros2/index.md"};function i(l,a,n,d,c,S){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h1><p>ROS 2 是ROS (机器人操作系统)最新版本 ， 一个通用的机器人库，可以与 PX4 自驾仪一起创建强大的无人机应用。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>小提示 PX4开发团队强烈建议您使用/迁移到此版本的 ROS！</p><p>这是最新版本的 <a href="https://www.ros.org/" target="_blank" rel="noreferrer">ROS</a> (机器人操作系统)。 它大大改进了外空军备竞赛“1”，尤其是允许与PX4更深、更低的延迟结合。</p></div><p>ROS得益于一个活跃的生态系统，在这个生态系统里，开发者会解决常见的机器人问题，他们也有权使用为Linux编写的其他软件库。 例如，它可以用于<a href="./../computer_vision/">计算机视图</a>解决方案。</p><p>ROS 2能够非常深入地与 PX4 集成 只要你可以在交战规则2中创建无法与内部的 PX4 模式区分的飞行模式， 并以高费率直接读取内部uORB主题。 建议（尤其是）从同伴计算机进行控制和通信，因为这种计算机的延迟率很低。 当利用来自Linux的现有库时，或在编写新的高层飞行模式时。</p><p>ROS 2 和 PX4 之间的通信使用中间件实现[XRCE-DDS] (../middleware/uxrce_dds.md)。 这个中间件将以 ROS 2 消息和类型显示 PX4 <a href="./../msg_docs/">uORB 消息</a>， 有效地允许从 ROS 2 工作流和节点直接访问 PX4。 中间件使用 uORB 消息定义生成代码来序列化和反序列化来处理PX4 的收发消息。 在ROS 2 应用中使用相同的消息定义可直接进行解析。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ROS 2 也可以使用 [MAVROS](<a href="https://github.com/mavlink/mavros/tree/ros2/mavros%E8%80%8C%E4%B8%8D%E6%98%AF" target="_blank" rel="noreferrer">https://github.com/mavlink/mavros/tree/ros2/mavros而不是</a> XRCE-DDS连接到 PX4。 这一备选办法得到了MAVROS项目的支持(此处没有记录)。</p></div><p>在XRCE-DDS上有效使用<a href="./../ros2/user_guide.html">ROS2</a>。 (撰写本文时)你必须对PX4内部结构和公约有合理的理解，这些结构和公约不同于交战规则所用的内部结构和公约。 我们计划近期提供ROS 2 API 以对 PX4 的特性进行封装，并举例说明它们的用途。</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><p>本节的主要主题是：</p><ul><li>ROS 2 用户指南: PX4 视角下的 ROS 2，包括安装、设置和如何构建与 PX4 通信的 ROS 2 应用。</li><li><a href="./../ros2/offboard_control.html">ROS 2 离板控制示例</a>：一个 C++ 教程示例显示如何在 [离板模式] (../flight_modes/offboard.md) 中使用 ROS 2 节点进行位置控制。</li><li><a href="./../ros2/multi_vehicle.html">ROS 2 多车辆模拟</a>：通过单独的ROS2 代理商连接到多极PX4 模拟的说明。</li><li><a href="./../ros2/px4_ros2_interface_lib.html">PX4 ROS2 接口库</a>：一个C++ 库，它与ROS2的 PX4 交互。 可以使用 ROS 2 创建和注册飞行模式，并从 ROS2 应用程序如VIO 系统发送位置估计数。</li><li><a href="./../ros2/px4_ros2_msg_translation_node.html">ROS 2 消息翻译节点</a>：一个 ROS 2 消息翻译节点，它允许在 PX4 和 ROS 2 应用程序之间共享，这些应用程序被编译成不同的消息版本。</li></ul><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="./../middleware/uxrce_dds.html">XRCE-DDS (PX4-ROS 2/DDS Bridge)</a>: PX4 使用中间件链接到 ROS 2。</li></ul>',13)]))}const R=e(s,[["render",i]]);export{p as __pageData,R as default};
